'use strict';
let CASES=[], SOURCES={};
const CONFIG=window.LPN_CONFIG;
const configured=Boolean(CONFIG.supabaseUrl&&CONFIG.supabasePublicKey);
const STAGES=['Patient chart','Research','Quick quiz','Simulation','Debrief','Lab preparation','Lab documentation'];
const LEVELS=['','Foundations','Older adults & complex care','Care across the lifespan','Acute care & integration'];
const app=document.getElementById('app');
let session=null,profile=null,records={},reviews={},assignments=[],people=[],invites=[],selectedReview=null;
let view='library',activeCase=null,stage=0,filter={q:'',level:'',status:''},saveTimer,saveChain=Promise.resolve(),mode='preview';
let transientQuiz={},simFeedback=null,busy=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(s)=>`<span class="symbol" aria-hidden="true">${s}</span>`;
const isInstructor=()=>mode==='cloud'&&profile?.role==='instructor';
const currentUser=()=>profile?.display_name||session?.user?.email||'Signed out';
function toast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4500)}
function stored(k,fallback){try{return JSON.parse(localStorage.getItem(k))||fallback}catch{return fallback}}
function keyFor(c){return c.id}
function record(c){return records[keyFor(c)]||{case_id:c.id,answers:{research:[],quiz:[],sim:[],debrief:[],completed:[],checklist:[],note:'',sbar:''},status:'draft'}}
function answers(c){const r=record(c);r.answers={research:[],quiz:[],sim:[],debrief:[],completed:[],checklist:[],note:'',sbar:'',...r.answers};return r.answers}
function setRecord(c,patch={}){const r=record(c);records[c.id]={...r,...patch,case_id:c.id,updated_at:new Date().toISOString()};queueSave(c)}
function setAnswer(c,k,value){const a=answers(c);a[k]=value;setRecord(c,{answers:a})}
function mark(c,n){const a=answers(c);a.completed=[...new Set([...a.completed,n])];setRecord(c,{answers:a})}
function queueSave(c){clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist(c),450);const el=document.getElementById('save-state');if(el)el.textContent='Saving…'}
async function persist(c){clearTimeout(saveTimer);const snapshot=JSON.parse(JSON.stringify(record(c)));saveChain=saveChain.catch(()=>{}).then(async()=>{try{if(mode==='preview'){localStorage.setItem('lpn-preview-v1',JSON.stringify(records))}else{await api('submissions?on_conflict=user_id,case_id',{method:'POST',body:{user_id:session.user.id,case_id:c.id,answers:snapshot.answers,status:snapshot.status},prefer:'resolution=merge-duplicates,return=representation'})}const el=document.getElementById('save-state');if(el)el.textContent=mode==='preview'?'Saved in this browser':'Saved to your account';return true}catch(e){const el=document.getElementById('save-state');if(el)el.textContent='Not saved. Try again.';toast('Save failed: '+e.message);return false}});return saveChain}
async function token(){if(!session)return '';if(session.expires_at&&Date.now()/1000>session.expires_at-60){const r=await fetch(CONFIG.supabaseUrl+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:CONFIG.supabasePublicKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});const d=await r.json();if(!r.ok)throw Error('Session expired. Sign in again.');session=d;sessionStorage.setItem('lpn-session',JSON.stringify(d))}return session.access_token}
async function api(path,{method='GET',body,prefer}={}){const t=await token();if(!t)throw Error('Sign in to continue.');const r=await fetch(CONFIG.supabaseUrl+'/rest/v1/'+path,{method,headers:{apikey:CONFIG.supabasePublicKey,Authorization:'Bearer '+t,'Content-Type':'application/json',...(prefer?{Prefer:prefer}:{})},...(body?{body:JSON.stringify(body)}:{})});if(!r.ok){const d=await r.json().catch(()=>({}));throw Error(d.message||'The request could not be completed.')}return r.status===204?null:r.json().catch(()=>null)}
async function loadAccount(){const p=await api('profiles?id=eq.'+session.user.id+'&select=*');if(!p.length)throw Error('No classroom profile found. Ask your instructor to check your invitation.');profile=p[0];const [rs,rv,as]=await Promise.all([api('submissions?select=*&order=updated_at.desc'),api('reviews?select=*'),api('assignments?select=*')]);records={};rs.forEach(r=>{if(r.user_id===session.user.id)records[r.case_id]=r});window.allSubmissions=rs;reviews={};rv.forEach(r=>reviews[r.user_id+':'+r.case_id]=r);assignments=as;if(profile.role==='instructor'){[people,invites]=await Promise.all([api('profiles?select=id,display_name,role'),api('invitations?select=email,display_name,created_at')])}const content=await api('clinical_content?id=eq.curriculum&select=payload');if(!content.length)throw Error('Classroom content is unavailable.');CASES=content[0].payload.cases;SOURCES=content[0].payload.sources;LAB_SKILLS=content[0].payload.labSkills||[];mode='cloud'}
function preview(){labPause();labRun=null;LAB_SKILLS=[];labRuns=[];mode='locked';CASES=[];SOURCES={};records={};reviews={};profile=null;assignments=[];people=[];invites=[];activeCase=null;window.allSubmissions=[]}
function nav(){if(mode!=='cloud')return `<aside class="rail"><a href="#account" class="brand"><span class="brand-icon" aria-hidden="true">+</span><span>Claire’s Clinical Lab<small>Practical nursing · British Columbia</small></span></a><p class="rail-note">Sign in with your invited classroom account to access case studies.</p><a class="btn secondary" href="#account">Sign in</a></aside>`;return `<aside class="rail"><a href="#library" class="brand"><span class="brand-icon" aria-hidden="true">+</span><span>Claire’s Clinical Lab<small>Practical nursing · British Columbia</small></span></a><nav class="nav" aria-label="Main navigation"><a href="#library" class="${view==='library'||view==='case'?'active':''}">${icon('▦')}Case library</a><a href="#lab" class="${view==='lab'?'active':''}">${icon('✓')}Lab Practice</a><a href="#progress" class="${view==='progress'?'active':''}">${icon('◷')}My progress</a>${isInstructor()?`<a href="#instructor" class="${view==='instructor'?'active':''}">${icon('▤')}Instructor view</a>`:''}<a href="#resources" class="${view==='resources'?'active':''}">${icon('≡')}Resources & scope</a></nav><div class="rail-note"><strong>Learn. Decide. Practise.</strong>Bring your reasoning from the patient chart into the skills lab.<p class="small" style="color:#c5d2e3;margin:14px 0 0">Fictional cases · Faculty review pending</p></div><a class="btn secondary" href="#account">${mode==='cloud'?'Account':'Student sign-in'}</a></aside>`}
function shell(content){app.innerHTML=`<div class="shell">${nav()}<div class="workspace"><header class="topbar"><span class="crumb">Clinical learning / ${view==='case'?'Case study':esc(view[0].toUpperCase()+view.slice(1))}</span><div class="userbar"><span class="badge ${mode==='preview'?'warning':''}">${mode==='preview'?'Browser-local preview':mode!=='cloud'?'Sign-in required':profile?.role==='instructor'?'Instructor':'Student'}</span><span class="small">${esc(currentUser())}</span><span class="avatar" aria-hidden="true">${esc(currentUser().slice(0,1).toUpperCase())}</span></div></header><main id="main" tabindex="-1">${mode==='preview'?'<div class="mode-banner">Practice preview: work is saved only in this browser. No student account or shared classroom is connected to this session. Use fictional information.</div>':''}${content}<footer class="footer">Original educational case drafts mapped to PN1006–PN4006 course packets. Not BCCNM-endorsed. Online completion does not establish clinical competence. Case lab rubrics are drafts. Lab Practice uses the supplied skill checklists; faculty determines competency.</footer></main></div></div>`;bindCommon()}
function bindCommon(){document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>location.hash='case/'+b.dataset.case);document.querySelectorAll('[data-action="print"]').forEach(b=>b.onclick=()=>window.print())}
function caseStats(){const rs=Object.values(records);return {started:rs.length,complete:rs.filter(r=>r.status==='submitted').length}}
function library(){const s=caseStats();shell(`<div class="heading"><div><p class="eyebrow">The case library</p><h1>Practise the decisions behind the skills.</h1><p class="muted">Explore a patient chart, investigate the evidence, then work through a clinical scenario before lab.</p></div><span class="badge">48 cases · 4 levels</span></div><div class="stats"><div class="stat"><span>Available case drafts</span><strong>48</strong></div><div class="stat"><span>Cases started</span><strong>${s.started}</strong></div><div class="stat"><span>Online work submitted</span><strong>${s.complete}</strong></div></div>${assignments.length?`<div class="panel"><h2>Your assigned cases</h2><div class="pill-row">${assignments.map(a=>`<a class="btn secondary compact" href="#case/${esc(a.case_id)}">${esc(a.case_id)}${a.due_date?' · '+esc(a.due_date):''}</a>`).join('')}</div></div>`:''}<div class="toolbar"><div class="search-field"><label for="search">Search cases, skills or keywords</label><input id="search" type="search" placeholder="Try wound care, insulin, consent…" value="${esc(filter.q)}"></div><div><label for="level-filter">Curriculum level</label><select id="level-filter"><option value="">All levels</option>${[1,2,3,4].map(l=>`<option value="${l}" ${filter.level==l?'selected':''}>Level ${l}</option>`).join('')}</select></div><div><label for="status-filter">Your progress</label><select id="status-filter"><option value="">All cases</option><option value="new" ${filter.status==='new'?'selected':''}>Not started</option><option value="draft" ${filter.status==='draft'?'selected':''}>In progress</option><option value="submitted" ${filter.status==='submitted'?'selected':''}>Submitted</option></select></div></div><p id="result-count" class="small" role="status"></p><div id="catalog" class="catalog-grid"></div>`);drawCards();document.getElementById('search').oninput=e=>{filter.q=e.target.value;drawCards()};document.getElementById('level-filter').onchange=e=>{filter.level=e.target.value;drawCards()};document.getElementById('status-filter').onchange=e=>{filter.status=e.target.value;drawCards()}}
function drawCards(){const cs=CASES.filter(c=>(!filter.level||c.level==filter.level)&&(!filter.q||[c.title,c.skill,c.patient,...c.tags].join(' ').toLowerCase().includes(filter.q.toLowerCase()))&&(!filter.status||(records[c.id]?.status||'new')===filter.status));document.getElementById('result-count').textContent=`${cs.length} ${cs.length===1?'case':'cases'} shown · Session numbers identify the teaching session to complete before practice.`;document.getElementById('catalog').innerHTML=cs.length?cs.map(c=>`<article class="case-card"><div class="card-top"><span class="badge level-${c.level}">Level ${c.level}</span><span class="case-id">${c.id} · S${c.session}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.patient)}<br>${esc(c.setting)}</p><div class="tags">${c.tags.slice(0,2).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}${c.theoryOnly?'<span class="tag">Theory only</span>':''}</div><div class="card-bottom"><span class="small">${records[c.id]?.status==='submitted'?'Submitted':records[c.id]?'In progress':'Not started'}</span><a class="btn compact ${records[c.id]?'':'secondary'}" href="#case/${c.id}">${records[c.id]?'Continue':'Open case'}</a></div></article>`).join(''):'<div class="empty"><h2>No cases match</h2><p>Try a different keyword or level.</p></div>'}
function patient(c){return `<aside class="patient-card"><div class="patient-initial" aria-hidden="true">${esc(c.patient.split(' ').slice(0,2).map(x=>x[0]).join(''))}</div><p class="small" style="margin:14px 0 0">Fictional patient</p><h2>${esc(c.patient)}</h2><p class="small">${esc(c.setting)}</p><dl><dt>Course</dt><dd>PN${c.level}006 · Level ${c.level}</dd><dt>Preparation</dt><dd>After session ${c.session}</dd><dt>Skill focus</dt><dd>${esc(c.skill)}</dd><dt>Case status</dt><dd>Faculty review pending</dd></dl><hr><p class="small">${esc(c.theoryOnly?'Theory-only activity. No practical insertion sign-off.':'Work within your agreed supervision plan. Use your approved lab checklist for procedure steps.')}</p><a href="#resources" class="small">Standards and learning limits</a></aside>`}
function caseView(){const c=activeCase,a=answers(c);shell(`<a href="#library" class="small">Back to case library</a><div class="heading" style="margin-top:18px"><div><p class="eyebrow">${c.id} · ${esc(LEVELS[c.level])}</p><h1>${esc(c.title)}</h1></div><span id="save-state" class="save-state">${records[c.id]?(mode==='preview'?'Saved in this browser':'Saved to your account'):'Not started'}</span></div><nav class="stepper" aria-label="Case stages">${STAGES.map((s,n)=>`<button data-stage="${n}" class="${stage===n?'current':a.completed.includes(n)?'completed':''}" ${stage===n?'aria-current="step"':''}>${a.completed.includes(n)?'✓':n+1} ${s}</button>`).join('')}</nav><div class="case-layout">${patient(c)}<section id="stage-content">${stageContent(c,a)}</section></div>`);document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=async()=>{await persist(c);stage=+b.dataset.stage;simFeedback=null;caseView();focusMain()});bindStage(c,a)}
function stageContent(c,a){if(stage===0)return `<div class="panel"><p class="eyebrow">01 / Patient chart</p><h2>Begin with the person.</h2><p>${esc(c.profile)}</p><h3>Learning objectives</h3><ul class="inline-list">${c.objectives.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><dl>${Object.entries(c.chart).filter(([k])=>k!=='Current narrative').map(([k,v])=>`<div class="chart-row"><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></div>${footerButtons()}`;
if(stage===1)return `<div class="panel"><p class="eyebrow">02 / Guided research</p><h2>Make the evidence useful.</h2><p class="muted">Explain your reasoning in your own words. Include the source title, date and link where relevant.</p>${c.research.map((p,i)=>`<div class="field"><label for="research-${i}">${i+1}. ${esc(p)}</label><textarea id="research-${i}" data-answer="research" data-index="${i}" placeholder="Your reasoning and supporting source…">${esc(a.research[i]||'')}</textarea></div>`).join('')}<details open><summary>Suggested starting resources</summary>${sourceList(c)}</details><p class="small">Suggested reading topic: ${esc(c.readingTopic)}. The 2015 skills text is background reading, not a substitute for current approved procedures.</p></div>${footerButtons()}`;
if(stage===2)return `<div class="panel"><p class="eyebrow">03 / Readiness quiz</p><h2>Check the reasoning.</h2><p class="muted">Three practice questions. Feedback is formative; retries remain visible in your recorded attempts.</p>${c.quiz.map((q,i)=>`<fieldset class="question"><legend>${i+1}. ${esc(q.prompt)}</legend>${order(q.options.length,c,i).map(j=>`<label class="choice"><input type="radio" name="quiz-${i}" value="${j}" ${a.quiz[i]===j?'checked':''}><span>${esc(q.options[j])}</span></label>`).join('')}${transientQuiz[c.id]||a.quizChecked?`<div class="feedback ${a.quiz[i]===q.answer?'':'incorrect'}"><strong>${a.quiz[i]===q.answer?'Correct':'Review this decision'}</strong>${esc(q.rationale)}</div>`:''}</fieldset>`).join('')}<button class="btn" id="check-quiz">Check my answers</button>${a.quizScore!==undefined?`<p class="small" style="margin-top:14px">Most recent practice result: ${a.quizScore}/3. This does not determine lab competence.</p>`:''}</div>${footerButtons()}`;
if(stage===3){const solved=c.simulation.map((_,n)=>a.sim.some(x=>x.step===n&&x.safe));const idx=solved.findIndex(v=>!v);if(idx<0)return `<div class="panel"><p class="eyebrow">04 / Simulation</p><h2>Scenario completed.</h2><p>You worked through both decisions. Review your path, then write a patient-specific handover.</p>${simLog(c,a)}<div class="field"><label for="sbar">Your SBAR handover</label><p class="small">Situation, Background, Assessment, Recommendation. Describe missing information explicitly.</p><textarea id="sbar" data-answer="sbar">${esc(a.sbar)}</textarea></div><div class="field"><label for="note">Your objective care note</label><textarea id="note" data-answer="note">${esc(a.note)}</textarea></div></div>${footerButtons()}`;const sc=c.simulation[idx];return `<div class="panel"><p class="eyebrow">04 / Simulation · Decision ${idx+1} of 2</p><div class="progress-track"><span style="width:${idx*50}%"></span></div><h2 style="margin-top:22px">What will you do next?</h2><p class="small">The patient information is scripted. Choose an action and explain your reasoning. A teaching pause follows an unsafe choice.</p><div class="cue">${esc(sc.prompt)}</div><fieldset class="question"><legend>Choose your next action</legend>${order(sc.choices.length,c,idx+4).map(j=>`<label class="choice"><input type="radio" name="sim-choice" value="${j}"><span>${esc(sc.choices[j].text)}</span></label>`).join('')}</fieldset><div class="field"><label for="sim-reason">Why this action?</label><textarea id="sim-reason" placeholder="Connect your action to the cues, risks and supervision plan.">${esc(a.simDraft||'')}</textarea></div>${simFeedback?`<div class="feedback ${simFeedback.safe?'':'incorrect'}"><strong>Teaching pause</strong>${esc(simFeedback.feedback)}</div>`:''}<button class="btn" id="sim-commit" data-step="${idx}">Commit decision</button></div>${footerButtons()}`}
if(stage===4)return `<div class="panel"><p class="eyebrow">05 / Debrief</p><h2>Turn the experience into a plan.</h2>${c.debrief.map((p,i)=>`<div class="field"><label for="debrief-${i}">${i+1}. ${esc(p)}</label><textarea id="debrief-${i}" data-answer="debrief" data-index="${i}">${esc(a.debrief[i]||'')}</textarea></div>`).join('')}<details><summary>Review your simulation decisions</summary>${simLog(c,a)}</details></div>${footerButtons()}`;
if(stage===6)return `<div class="panel"><p class="eyebrow">07 / Lab documentation</p><h2>Document your findings after practice.</h2><p class="muted">${c.theoryOnly?'Record findings from the theory discussion or simulated review only. Do not perform the restricted practical skill.':'Complete this after supervised lab practice. Use objective observations and identify measurements you actually obtained.'}</p><div class="notice">Use the fictional case or simulation identifier. Do not enter real patient identifiers. ${esc(c.lab.restriction)}</div>${labField('labFindings','Assessment findings','What did you observe or measure? Include relevant values and units, if obtained.',a)}${labField('labPerformed','Interventions performed','What did you actually do, and in what sequence? Include supervision or assistance received.',a)}${labField('labResponse','Response and reassessment','How did the simulated patient respond? What did you reassess?',a)}${labField('labFollowUp','Follow-up and communication','What needs further assessment, escalation, handover or practice?',a)}<div class="actions"><button class="btn" id="submit-lab">${a.labDocumentedAt?'Update lab documentation':'Submit lab documentation'}</button><button class="btn secondary" data-action="print">Print lab documentation</button></div>${a.labDocumentedAt?`<div class="feedback">Lab documentation submitted: ${esc(new Date(a.labDocumentedAt).toLocaleString())}. This does not establish a lab pass.</div>`:''}${reviewBlock(c)}</div>${footerButtons()}`;
return `<div class="panel"><p class="eyebrow">06 / Lab preparation</p><h2>${esc(c.lab.title)}</h2><p>${esc(c.lab.focus)}</p><div class="notice">${esc(c.lab.restriction)}</div><h3>Your priority plan</h3><p class="small">Identify one priority assessment and the interventions you plan to implement. Explain how they address this case and follow your supervision plan.</p>${labField('priorityAssessment','One priority assessment','Name one assessment, explain why it takes priority, and describe how you will assess it.',a)}${labField('plannedInterventions','Planned interventions','Describe your planned interventions, their rationale, and how you will evaluate the response.',a)}<h3>Equipment and preparation</h3><p>${esc(c.lab.equipment)}</p><h3>Self-check before lab</h3><p class="small">These checkboxes record preparation, not instructor assessment.</p>${c.lab.criteria.map((t,i)=>`<label class="choice"><input type="checkbox" data-check="${i}" ${a.checklist.includes(i)?'checked':''}><span>${esc(t)}</span></label>`).join('')}<div class="actions"><button class="btn secondary" data-action="print">Print lab preparation</button><button class="btn" id="submit-case">${record(c).status==='submitted'?'Update submission':'Submit online work'}</button></div>${record(c).status==='submitted'?'<div class="feedback">Online work submitted. Lab performance remains a separate instructor assessment.</div>':''}${reviewBlock(c)}<details><summary>Sources and curriculum mapping</summary><p>${esc(c.packet)}. Mapping is based on the supplied course packet; the packet is not redistributed.</p>${sourceList(c)}</details></div>${footerButtons()}`}
function order(n,c,offset){const start=(parseInt(c.id.slice(-2))+offset)%n;return Array.from({length:n},(_,i)=>(i+start)%n)}
function labField(key,label,prompt,a){return `<div class="field"><label for="${key}">${esc(label)}</label><p class="small">${esc(prompt)}</p><textarea id="${key}" data-answer="${key}" required>${esc(a[key]||'')}</textarea></div>`}
function footerButtons(){return `<div class="actions"><button class="btn secondary" id="previous" ${stage===0?'disabled':''}>Previous stage</button><button class="btn secondary" id="save-now">Save work</button>${stage<STAGES.length-1?'<button class="btn" id="next">Save & continue</button>':'<a class="btn secondary" href="#library">Case library</a>'}</div>`}
function sourceList(c){return `<ul class="sources">${c.references.map(k=>`<li><a href="${SOURCES[k].url}" target="_blank" rel="noopener noreferrer">${esc(SOURCES[k].title)}</a><small>${esc(SOURCES[k].note)}</small></li>`).join('')}</ul>`}
function simLog(c,a){return a.sim.length?`<ol class="inline-list">${a.sim.map(s=>`<li><strong>Decision ${s.step+1}: ${s.safe?'Progressed':'Teaching pause'}</strong><br>${esc(c.simulation[s.step].choices[s.choice].text)}<p class="small">Reason: ${esc(s.reason)}</p></li>`).join('')}</ol>`:'<p class="muted">No decisions recorded yet.</p>'}
function reviewBlock(c){const r=reviews[(mode==='preview'?'preview':session.user.id)+':'+c.id];return r&&r.released?`<div class="panel"><h3>Instructor feedback</h3><p>${esc(r.feedback||'No written feedback.')}</p><p><strong>Lab outcome:</strong> ${esc(r.lab_outcome)}</p></div>`:'<p class="small">No instructor feedback released yet.</p>'}
function validateStage(c,n){const a=answers(c);if(n===1&&!c.research.every((_,i)=>a.research[i]?.trim()))return 'Complete the three research responses first.';if(n===2&&!a.quizChecked)return 'Check your quiz answers first.';if(n===3&&(!c.simulation.every((_,i)=>a.sim.some(s=>s.step===i&&s.safe))||!a.sbar.trim()||!a.note.trim()))return 'Complete both simulation decisions, your SBAR and care note first.';if(n===4&&!c.debrief.every((_,i)=>a.debrief[i]?.trim()))return 'Complete the three debrief responses first.';if(n===5&&(!a.priorityAssessment?.trim()||!a.plannedInterventions?.trim()))return 'Identify one priority assessment and your planned interventions first.';if(n===6&&!['labFindings','labPerformed','labResponse','labFollowUp'].every(k=>a[k]?.trim()))return 'Complete all four lab documentation fields first.';return ''}
function bindStage(c,a){document.querySelectorAll('[data-answer]').forEach(el=>el.oninput=()=>{const k=el.dataset.answer,idx=el.dataset.index;if(idx!==undefined){const arr=[...answers(c)[k]];arr[+idx]=el.value;setAnswer(c,k,arr)}else setAnswer(c,k,el.value)});document.querySelectorAll('[data-check]').forEach(el=>el.onchange=()=>{const set=new Set(answers(c).checklist);el.checked?set.add(+el.dataset.check):set.delete(+el.dataset.check);setAnswer(c,'checklist',[...set])});document.querySelectorAll('input[name^="quiz-"]').forEach(el=>el.onchange=()=>{const arr=[...answers(c).quiz];arr[+el.name.split('-')[1]]=+el.value;setAnswer(c,'quiz',arr);setAnswer(c,'quizChecked',false);delete transientQuiz[c.id]});const $=id=>document.getElementById(id);if($('save-now'))$('save-now').onclick=async()=>{if(await persist(c))toast('Work saved.')};if($('previous'))$('previous').onclick=async()=>{await persist(c);stage--;simFeedback=null;caseView();focusMain()};if($('next'))$('next').onclick=async()=>{const msg=validateStage(c,stage);if(msg)return toast(msg);mark(c,stage);if(!await persist(c))return;stage++;simFeedback=null;caseView();focusMain()};if($('check-quiz'))$('check-quiz').onclick=async()=>{const aa=answers(c);if(!c.quiz.every((q,i)=>Number.isInteger(aa.quiz[i])))return toast('Choose an answer for every question.');aa.quizScore=c.quiz.reduce((s,q,i)=>s+(aa.quiz[i]===q.answer?1:0),0);aa.quizAttempts=[...(aa.quizAttempts||[]),{answers:[...aa.quiz],score:aa.quizScore,at:new Date().toISOString()}];aa.quizChecked=true;setRecord(c,{answers:aa});transientQuiz[c.id]=true;await persist(c);caseView()};if($('sim-reason'))$('sim-reason').oninput=e=>setAnswer(c,'simDraft',e.target.value);if($('sim-commit'))$('sim-commit').onclick=async()=>{const chosen=document.querySelector('input[name="sim-choice"]:checked'),reason=$('sim-reason').value.trim();if(!chosen||!reason)return toast('Choose an action and explain your reasoning.');const idx=+$('sim-commit').dataset.step,j=+chosen.value,ch=c.simulation[idx].choices[j],aa=answers(c);aa.sim.push({step:idx,choice:j,safe:ch.safe,reason,at:new Date().toISOString()});aa.simDraft='';setRecord(c,{answers:aa});simFeedback=ch.safe?null:ch;await persist(c);caseView();if(ch.safe)toast(ch.feedback);focusMain()};if($('submit-case'))$('submit-case').onclick=async()=>{for(let n=1;n<=5;n++){const msg=validateStage(c,n);if(msg)return toast(msg)}if(answers(c).checklist.length<c.lab.criteria.length)return toast('Complete the lab preparation self-check first.');mark(c,5);setRecord(c,{status:'submitted'});if(await persist(c)){toast(mode==='preview'?'Submitted in this browser preview. No instructor receives this.':'Submitted to your instructor.');caseView()}};if($('submit-lab'))$('submit-lab').onclick=async()=>{const msg=validateStage(c,6);if(msg)return toast(msg);mark(c,6);setAnswer(c,'labDocumentedAt',new Date().toISOString());if(await persist(c)){toast('Lab documentation submitted to your instructor.');caseView()}};bindCommon()}
function focusMain(){document.getElementById('main')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}
function progress(){const rs=Object.values(records);shell(`<p class="eyebrow">Your learning record</p><h1>My progress</h1><p class="muted">Online preparation and instructor-observed lab performance are tracked separately.</p>${rs.length?`<div class="table-wrap"><table><thead><tr><th>Case</th><th>Online status</th><th>Practice quiz</th><th>Lab outcome</th><th></th></tr></thead><tbody>${rs.map(r=>{const c=CASES.find(c=>c.id===r.case_id);if(!c)return '';const rev=reviews[(mode==='preview'?'preview':session.user.id)+':'+c.id];return `<tr><td><strong>${c.id}</strong><br>${esc(c.title)}</td><td>${esc(r.status==='submitted'?'Submitted':'In progress')}</td><td>${r.answers.quizScore===undefined?'Not checked':r.answers.quizScore+'/3'}</td><td>${rev?.released?esc(rev.lab_outcome):'Not assessed / not released'}</td><td><a href="#case/${c.id}">Open</a></td></tr>`}).join('')}</tbody></table></div><div class="actions"><button class="btn secondary" id="export-own">Download my work</button></div>`:'<div class="empty"><h2>Your first case is waiting.</h2><p>Start with your current level and the skills you have already covered.</p><a class="btn" href="#library">Browse cases</a></div>'}`);document.getElementById('export-own')?.addEventListener('click',()=>download('my-clinical-lab-work.json',JSON.stringify({exported_at:new Date().toISOString(),records:rs},null,2),'application/json'))}
function resources(){shell(`<p class="eyebrow">Evidence and learning boundaries</p><h1>Resources & scope</h1><div class="panel"><h2>Use the case as a starting point.</h2><p>All patients and events are fictional. Cases are original educational drafts and require faculty review before classroom release. They are not clinical orders, institutional protocols or BCCNM-endorsed teaching materials.</p><p>Each case identifies the course and recommended teaching session. The supplied packets determine the initial mapping. Your demonstrated readiness and agreed supervision plan determine participation in clinical care.</p><h3>Theory-only content in PN4006</h3><p>IV insertion, IV medication administration, initiating blood products and inserting nasogastric tubes remain theory/knowledge only in this version. The packet’s IV insertion schedule is ambiguous; the explicit theory-only restriction is retained pending clarification.</p><h3>Lab assessment</h3><p>Draft lab criteria support preparation and reasoning. They do not replace the Skills Book, equipment-specific instructions, or the official skills and Integrated Nursing Practice Assessment checklists.</p><h3>Practice results</h3><p>Quiz and simulation scores are learning feedback, not secure examination marks. Classroom content is retrieved only after sign-in. Practice scores remain formative. Instructor lab judgments are recorded separately.</p></div><div class="panel"><h2>Reference library</h2><ul class="sources">${Object.values(SOURCES).map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a><small>${esc(s.note)}</small></li>`).join('')}</ul><p class="small">The source packets are not included in the public website. Case-specific clinical procedures, medication details and local policy requirements must be checked against current approved resources before teaching.</p></div>`)}
function instructor(){if(!isInstructor()){shell('<div class="empty"><h1>Instructor access required</h1><p>Your student account cannot access other students’ work.</p></div>');return}const rs=mode==='preview'?Object.values(records).map(r=>({...r,user_id:'preview'})):(window.allSubmissions||[]);shell(`<div class="heading"><div><p class="eyebrow">Instructor workspace</p><h1>Review reasoning. Assess practice.</h1><p class="muted">${mode==='preview'?'This preview shows only work entered in this browser. It is not an instructor login.':'Manage your classroom and review student submissions.'}</p></div><button class="btn secondary" id="refresh-instructor">Refresh</button></div><div class="stats"><div class="stat"><span>${mode==='preview'?'Preview learner':'Student accounts'}</span><strong>${mode==='preview'?1:people.filter(p=>p.role==='student').length}</strong></div><div class="stat"><span>Submissions to review</span><strong>${rs.filter(r=>r.status==='submitted').length}</strong></div><div class="stat"><span>Case drafts</span><strong>48</strong></div></div><div class="panel"><h2>Student work</h2>${rs.length?`<div class="table-wrap"><table><thead><tr><th>Learner</th><th>Case</th><th>Status</th><th>Practice quiz</th><th></th></tr></thead><tbody>${rs.map((r,i)=>`<tr><td>${esc(learnerName(r.user_id))}</td><td>${esc(r.case_id)}</td><td>${esc(r.status)}</td><td>${r.answers.quizScore===undefined?'Not checked':r.answers.quizScore+'/3'}</td><td><button class="btn secondary compact" data-review="${i}">Review</button></td></tr>`).join('')}</tbody></table></div><button class="btn secondary" style="margin-top:18px" id="export-class">Export summary CSV</button>`:'<p class="muted">No student work yet. In preview, complete part of a case to try the review workflow.</p>'}</div><div id="review-area"></div>${mode==='cloud'?`<div class="split"><div class="panel"><h2>Invite a student</h2><p class="small">Add an allowed email address. Share the site link yourself; this form does not send an invitation email. The student chooses “Create account” using that exact email.</p><form id="invite-form"><div class="field"><label for="invite-name">Student name</label><input id="invite-name" required maxlength="120"></div><div class="field"><label for="invite-email">Email address</label><input id="invite-email" type="email" required></div><button class="btn">Add invitation</button></form><p class="small">${invites.length} invitation records</p></div><div class="panel"><h2>Assign a case</h2><form id="assign-form"><div class="field"><label for="assign-student">Student</label><select id="assign-student" required><option value="">Choose a student</option>${people.filter(p=>p.role==='student').map(p=>`<option value="${p.id}">${esc(p.display_name)}</option>`).join('')}</select></div><div class="field"><label for="assign-case">Case</label><select id="assign-case">${CASES.map(c=>`<option value="${c.id}">${c.id} · ${esc(c.title)}</option>`).join('')}</select></div><div class="field"><label for="assign-due">Due date (optional)</label><input type="date" id="assign-due"></div><button class="btn">Assign case</button></form></div></div>`:'<div class="panel"><h2>Connect a classroom when you are ready</h2><p>The project includes account setup, an invitation-only student roster, private submissions, case assignments, and instructor reviews. Configure the supplied Supabase database and public connection settings to enable these tools.</p><a href="#account">View account setup status</a></div>'}`);document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>showReview(rs[+b.dataset.review]));document.getElementById('refresh-instructor').onclick=async()=>{try{if(mode==='cloud')await loadAccount();instructor()}catch(e){toast(e.message)}};document.getElementById('export-class')?.addEventListener('click',()=>{const rows=[['Learner','Case','Status','Practice quiz / 3','Updated'],...rs.map(r=>[learnerName(r.user_id),r.case_id,r.status,r.answers.quizScore??'',r.updated_at])];download('clinical-lab-summary.csv',rows.map(row=>row.map(csv).join(',')).join('\r\n'),'text/csv')});document.getElementById('invite-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('invitations',{method:'POST',body:{email:document.getElementById('invite-email').value.trim().toLowerCase(),display_name:document.getElementById('invite-name').value.trim()},prefer:'return=minimal'});toast('Invitation added. Share the website link with the student.');await loadAccount();instructor()}catch(e){toast(e.message)}});document.getElementById('assign-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('assignments?on_conflict=user_id,case_id',{method:'POST',body:{user_id:document.getElementById('assign-student').value,case_id:document.getElementById('assign-case').value,due_date:document.getElementById('assign-due').value||null},prefer:'resolution=merge-duplicates,return=minimal'});toast('Case assigned.');await loadAccount()}catch(e){toast(e.message)}})}
function learnerName(id){return id==='preview'?'Preview learner':people.find(p=>p.id===id)?.display_name||'Student'}
function showReview(r){selectedReview=r;const c=CASES.find(c=>c.id===r.case_id),a={research:[],quiz:[],sim:[],debrief:[],...r.answers},rev=reviews[r.user_id+':'+r.case_id]||{};document.getElementById('review-area').innerHTML=`<div class="panel"><p class="eyebrow">${esc(learnerName(r.user_id))} · ${c.id}</p><h2>${esc(c.title)}</h2><h3>Research</h3>${c.research.map((q,i)=>`<p><strong>${esc(q)}</strong></p><p class="review-text">${esc(a.research[i]||'Not answered')}</p>`).join('')}<details><summary>Quiz responses and attempts</summary>${c.quiz.map((q,i)=>`<p><strong>${esc(q.prompt)}</strong><br>${esc(q.options[a.quiz[i]]||'Not answered')}</p>`).join('')}<p class="small">Recorded attempts: ${(a.quizAttempts||[]).length}. Scores are self-practice feedback.</p></details><details open><summary>Simulation decision path</summary>${simLog(c,a)}</details><h3>SBAR and care note</h3><p class="review-text">${esc(a.sbar||'No SBAR')}</p><p class="review-text">${esc(a.note||'No care note')}</p><h3>Debrief</h3>${c.debrief.map((q,i)=>`<p><strong>${esc(q)}</strong></p><p class="review-text">${esc(a.debrief[i]||'Not answered')}</p>`).join('')}<h3>Lab preparation: priority plan</h3><p><strong>Priority assessment</strong></p><p class="review-text">${esc(a.priorityAssessment||'Not entered')}</p><p><strong>Planned interventions</strong></p><p class="review-text">${esc(a.plannedInterventions||'Not entered')}</p><h3>Post-practice lab documentation</h3>${[['labFindings','Assessment findings'],['labPerformed','Interventions performed'],['labResponse','Response and reassessment'],['labFollowUp','Follow-up and communication']].map(([k,label])=>`<p><strong>${label}</strong></p><p class="review-text">${esc(a[k]||'Not entered')}</p>`).join('')}<p class="small">${a.labDocumentedAt?'Submitted '+esc(new Date(a.labDocumentedAt).toLocaleString()):'Lab documentation not yet submitted'}</p><hr><form id="review-form"><h3>Instructor assessment</h3><p class="small">Draft criteria only. Record observed performance using your approved Skills Book. ${c.theoryOnly?'This is a theory-only case; no practical competency sign-off is offered.':''}</p>${c.lab.criteria.map((q,i)=>`<div class="field"><label for="criterion-${i}">${esc(q)}</label><select id="criterion-${i}">${['Not observed','Satisfactory','Needs further practice'].map(t=>`<option ${(rev.criteria||{})[i]===t?'selected':''}>${t}</option>`).join('')}</select></div>`).join('')}<div class="field"><label for="lab-outcome">${c.theoryOnly?'Theory review outcome':'Lab outcome'}</label><select id="lab-outcome">${(c.theoryOnly?['Not assessed','Theory reviewed','Further theory review needed']:['Not assessed','Pass','Further practice required','Reassessment required']).map(t=>`<option ${rev.lab_outcome===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="feedback">Written feedback</label><textarea id="feedback">${esc(rev.feedback||'')}</textarea></div><label class="choice"><input type="checkbox" id="release-feedback" ${rev.released?'checked':''}>Release this feedback to the student</label><button class="btn">Save instructor review</button></form></div>`;document.getElementById('review-form').onsubmit=async e=>{e.preventDefault();const data={user_id:r.user_id,case_id:r.case_id,feedback:document.getElementById('feedback').value,lab_outcome:document.getElementById('lab-outcome').value,released:document.getElementById('release-feedback').checked,criteria:Object.fromEntries(c.lab.criteria.map((_,i)=>[i,document.getElementById('criterion-'+i).value]))};try{if(mode==='cloud')await api('reviews?on_conflict=user_id,case_id',{method:'POST',body:data,prefer:'resolution=merge-duplicates,return=minimal'});reviews[r.user_id+':'+r.case_id]=data;if(mode==='preview')localStorage.setItem('lpn-preview-reviews',JSON.stringify(reviews));toast('Instructor review saved.')}catch(e){toast(e.message)}};document.getElementById('review-area').scrollIntoView({behavior:'smooth'})}
function csv(v){let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function account(){shell(`<div class="auth"><p class="eyebrow">Classroom access</p><h1>${mode==='cloud'?'Your account':'Classroom sign-in'}</h1>${mode==='cloud'?`<div class="panel"><p>Signed in as <strong>${esc(session.user.email)}</strong>.</p><p>Role: ${esc(profile.role)}</p><button class="btn secondary" id="logout">Sign out</button><div class="field"><label for="new-password">New password</label><input id="new-password" type="password" minlength="12" autocomplete="new-password"></div><button class="btn secondary" id="change-password">Update password</button></div>`:!configured?`<div class="panel"><h2>Classroom connection pending</h2><p>You can explore all cases and save practice work in this browser now.</p><p>Real accounts and shared submissions become available after the instructor connects the database using the included setup guide. There are no working shared login credentials in this preview.</p><a class="btn" href="#library">Continue practice preview</a></div>`:`<div class="panel"><p class="small">Use the email address your instructor invited. Your password is managed by the authentication service.</p><form id="auth-form" novalidate><div class="field"><label for="email">Email address</label><input id="email" type="email" required autocomplete="username"></div><div class="field"><label for="password">Password</label><input id="password" type="password" required autocomplete="current-password"></div><div class="actions"><button class="btn" name="intent" value="login">Sign in</button><button class="btn secondary" name="intent" value="signup">Create account</button></div></form><button class="text-button" id="reset-password">Send password reset email</button><div id="auth-message" role="status"></div></div>`}<p class="small">Case studies are available only to signed-in classroom members.</p></div>`);document.getElementById('logout')?.addEventListener('click',async()=>{try{await fetch(CONFIG.supabaseUrl+'/auth/v1/logout',{method:'POST',headers:{apikey:CONFIG.supabasePublicKey,Authorization:'Bearer '+await token()}})}finally{session=null;sessionStorage.removeItem('lpn-session');preview();location.hash='account';render()}});document.getElementById('change-password')?.addEventListener('click',async()=>{const p=document.getElementById('new-password').value;if(p.length<12)return toast('Use at least 12 characters.');try{const r=await fetch(CONFIG.supabaseUrl+'/auth/v1/user',{method:'PUT',headers:{apikey:CONFIG.supabasePublicKey,Authorization:'Bearer '+await token(),'Content-Type':'application/json'},body:JSON.stringify({password:p})});const d=await r.json();if(!r.ok)throw Error(d.msg||d.message||'Password update failed');toast('Password updated.');document.getElementById('new-password').value=''}catch(e){toast(e.message)}});document.getElementById('auth-form')?.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const intent=e.submitter?.value||'login',email=document.getElementById('email').value.trim(),password=document.getElementById('password').value;const message=document.getElementById('auth-message');try{if(!email||!document.getElementById('email').validity.valid)throw Error('Enter a valid email address.');if(!password)throw Error('Enter your password.');if(intent==='signup'&&password.length<12)throw Error('Use at least 12 characters when creating an account.');message.textContent=intent==='login'?'Signing in…':'Creating your account…';const r=await fetch(CONFIG.supabaseUrl+'/auth/v1/'+(intent==='login'?'token?grant_type=password':'signup?redirect_to='+encodeURIComponent(location.href.split('#')[0])),{method:'POST',headers:{apikey:CONFIG.supabasePublicKey,'Content-Type':'application/json'},body:JSON.stringify({email,password,...(intent==='signup'?{options:{emailRedirectTo:location.href.split('#')[0]}}:{})})});const d=await r.json();if(!r.ok)throw Error(d.msg||d.message||d.error_description||'Could not sign in. Check your invitation and credentials.');if(d.access_token){session=d;sessionStorage.setItem('lpn-session',JSON.stringify(d));await loadAccount();location.hash='library';render()}else message.textContent='Check your email for a confirmation link. Then return to sign in.'}catch(e){message.textContent=e.message||'Sign-in failed. Please try again.';message.setAttribute('role','alert');toast(message.textContent)}finally{busy=false}});document.getElementById('reset-password')?.addEventListener('click',async()=>{const email=document.getElementById('email').value.trim();if(!email)return toast('Enter your email address first.');try{const r=await fetch(CONFIG.supabaseUrl+'/auth/v1/recover?redirect_to='+encodeURIComponent(location.href.split('#')[0]),{method:'POST',headers:{apikey:CONFIG.supabasePublicKey,'Content-Type':'application/json'},body:JSON.stringify({email})});if(!r.ok)throw Error('Could not request a reset. Please try again.');toast('If the account exists, a reset email will be sent.')}catch(e){toast(e.message)}})}
function render(){if(mode!=='cloud'||!session||!profile){view='account';account();return}const route=location.hash.slice(1).split('/');view=route[0]||'library';if(view==='case'){activeCase=CASES.find(c=>c.id===route[1]);if(!activeCase){location.hash='library';return}caseView()}else if(view==='lab')labPractice();else if(view==='progress')progress();else if(view==='instructor')instructor();else if(view==='resources')resources();else if(view==='account')account();else{view='library';library()}}
window.addEventListener('hashchange',async()=>{if(labRun){labPause();clearTimeout(labSaveTimer);await labSave()}if(activeCase&&records[activeCase.id])await persist(activeCase);activeCase=null;stage=0;simFeedback=null;render();focusMain()});
window.addEventListener('pagehide',()=>{labPause();if(mode==='preview'){try{localStorage.setItem('lpn-preview-v1',JSON.stringify(records))}catch{}}});
async function boot(){preview();if(configured){try{const hash=new URLSearchParams(location.hash.slice(1));if(hash.has('access_token')){const t=hash.get('access_token');const r=await fetch(CONFIG.supabaseUrl+'/auth/v1/user',{headers:{apikey:CONFIG.supabasePublicKey,Authorization:'Bearer '+t}});if(!r.ok)throw Error('Confirmation link could not be verified.');session={access_token:t,refresh_token:hash.get('refresh_token'),expires_at:Date.now()/1000+Number(hash.get('expires_in')||3600),user:await r.json()};sessionStorage.setItem('lpn-session',JSON.stringify(session));history.replaceState(null,'',location.pathname+location.search+'#account')}else{try{session=JSON.parse(sessionStorage.getItem('lpn-session'))}catch{session=null}}if(session)await loadAccount()}catch(e){session=null;sessionStorage.removeItem('lpn-session');preview();toast(e.message)}}render()}
// Lab skill content is loaded only after classroom authentication.
let LAB_SKILLS=[], labRuns=[], labRun=null, labSection=0, labStartedAt=null, labTimer=null, labSaveChain=Promise.resolve(), labSaveTimer=null, labNewPending=false, labFinishPending=false;
function labActions(run){return run.checklist.sections.flatMap(s=>s.actions)}
function labSummary(run){const actions=labActions(run), results=run.results||{};const completed=actions.filter(a=>results[a.id]==='done'),na=actions.filter(a=>a.conditional&&results[a.id]==='na'), missed=actions.filter(a=>!completed.includes(a)&&!na.includes(a));return {completed,na,missed,cf:missed.filter(a=>a.cf),total:actions.length}}
function labSeconds(){return (labRun?.elapsed_seconds||0)+(labStartedAt===null?0:Math.floor((Date.now()-labStartedAt)/1000))}
function labTime(seconds){return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0')}
function labPause(){if(labStartedAt!==null&&labRun){labRun.elapsed_seconds=labSeconds();labStartedAt=null}clearInterval(labTimer);labTimer=null}
function labCanEdit(run){return run.status==='draft'&& (run.mode==='self'?run.learner_id===session.user.id:run.evaluator_id===session.user.id)}
async function labFetchRuns(){labRuns=await api('lab_practice_sessions?select=id,learner_id,evaluator_id,learner_name,evaluator_name,skill_id,skill_version,mode,status,created_at&order=created_at.desc')}
function labSave(){if(!labRun||!labCanEdit(labRun))return Promise.resolve(true);const snapshot={results:JSON.parse(JSON.stringify(labRun.results)),notes:JSON.parse(JSON.stringify(labRun.notes)),elapsed_seconds:labSeconds()};const id=labRun.id;labSaveChain=labSaveChain.catch(()=>{}).then(async()=>{try{await api('lab_practice_sessions?id=eq.'+id,{method:'PATCH',body:snapshot,prefer:'return=representation'});const el=document.getElementById('lab-save-state');if(el)el.textContent='Saved to your account';return true}catch(e){const el=document.getElementById('lab-save-state');if(el)el.textContent='Not saved. Try again.';toast('Practice save failed: '+e.message);return false}});return labSaveChain}
function labQueueSave(){clearTimeout(labSaveTimer);const el=document.getElementById('lab-save-state');if(el)el.textContent='Saving…';labSaveTimer=setTimeout(labSave,400)}
async function labPractice(){if(labRun){labDrawRun();return}shell(`<div class="heading"><div><p class="eyebrow">Skills practice</p><h1>Lab Practice</h1><p class="muted">Practise one action at a time. Review missed steps with your classmate or instructor.</p></div></div><div class="panel"><h2>Join as a peer evaluator</h2><p>Your classmate creates a peer practice run and shares its pairing code. Sign in to your own account, enter that code below, then evaluate their performance.</p><form id="lab-join"><label for="lab-code">Pairing code</label><input id="lab-code" required placeholder="Paste the code shared by your classmate" autocomplete="off"><button class="btn" style="margin-top:12px">Join peer practice</button><p id="lab-join-error" role="alert"></p></form></div><div class="catalog-grid">${LAB_SKILLS.map(s=>`<article class="panel"><p class="eyebrow">Available skill</p><h2>${esc(s.title)}</h2><p>15-minute practice target · ${s.sections.length} sections · Detailed comprehensive checklist</p><p class="small">Full source checklist, including preparation, history and documentation. The target is not an automatic pass/fail cutoff.</p><div class="actions"><button class="btn" data-lab-new="self" data-lab-skill="${esc(s.id)}">Self-practice</button><button class="btn secondary" data-lab-new="peer" data-lab-skill="${esc(s.id)}">Practice with a peer</button></div></article>`).join('')}</div><div class="panel"><h2>${isInstructor()?'Class practice records':'Your practice records'}</h2><button class="btn secondary compact" id="lab-refresh">Refresh records</button><div id="lab-run-list" style="margin-top:16px"><p>Loading practice records…</p></div></div>`);document.querySelectorAll('[data-lab-new]').forEach(b=>b.onclick=()=>labCreate(b.dataset.labSkill,b.dataset.labNew));document.getElementById('lab-join').onsubmit=async e=>{e.preventDefault();const el=document.getElementById('lab-join-error');try{const code=document.getElementById('lab-code').value.trim();if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(code))throw Error('Paste the complete pairing code.');await api('rpc/join_lab_practice',{method:'POST',body:{p_session_id:code}});await labOpen(code)}catch(err){el.textContent=err.message}};document.getElementById('lab-refresh').onclick=async()=>{try{await labFetchRuns();labList()}catch(e){toast(e.message)}};try{await labFetchRuns();if(view==='lab'&&!labRun)labList()}catch(e){const el=document.getElementById('lab-run-list');if(el)el.textContent='Could not load practice records: '+e.message}}
function labList(){const el=document.getElementById('lab-run-list');if(!el)return;el.innerHTML=labRuns.length?`<div class="table-wrap"><table><thead><tr><th>Learner</th><th>Practice</th><th>Evaluator</th><th>Status</th><th></th></tr></thead><tbody>${labRuns.map(r=>`<tr><td>${esc(r.learner_name)}</td><td>${esc(LAB_SKILLS.find(s=>s.id===r.skill_id)?.title||r.skill_id)}<br><small>${esc(new Date(r.created_at).toLocaleString())}</small></td><td>${esc(r.mode==='self'?'Self-practice':r.evaluator_name||'Waiting for peer')}</td><td>${esc(r.status)}</td><td><button class="btn secondary compact" data-lab-open="${r.id}">${r.status==='finished'?'Review':'Open'}</button></td></tr>`).join('')}</tbody></table></div>`:'<p>No practice runs yet.</p>';el.querySelectorAll('[data-lab-open]').forEach(b=>b.onclick=()=>labOpen(b.dataset.labOpen))}
async function labCreate(skillId,practiceMode){if(labNewPending)return;labNewPending=true;try{const skill=LAB_SKILLS.find(s=>s.id===skillId);if(!skill)throw Error('Skill content is unavailable.');const body={id:crypto.randomUUID(),learner_id:session.user.id,learner_name:profile.display_name||session.user.email,skill_id:skill.id,skill_version:skill.version,mode:practiceMode,checklist:skill};const rows=await api('lab_practice_sessions',{method:'POST',body,prefer:'return=representation'});labRun=rows[0];labSection=0;labDrawRun()}catch(e){toast(e.message)}finally{labNewPending=false}}
async function labOpen(id){try{labPause();clearTimeout(labSaveTimer);if(!await labSave())return;const rows=await api('lab_practice_sessions?id=eq.'+id+'&select=*');if(!rows.length)throw Error('This practice record is unavailable.');labRun=rows[0];labSection=0;labDrawRun()}catch(e){toast(e.message)}}
function labDrawRun(){if(!labRun)return;const r=labRun,editable=labCanEdit(r),s=r.checklist.sections[labSection],summary=labSummary(r);shell(`<a href="#lab" id="lab-back" class="small">Back to Lab Practice</a><div class="heading"><div><p class="eyebrow">${esc(r.mode==='self'?'Self-practice':'Peer evaluation')}</p><h1>${esc(r.checklist.title)}</h1><p>Learner: <strong>${esc(r.learner_name)}</strong> · Evaluator: ${esc(r.mode==='self'?r.learner_name:r.evaluator_name||'Not paired yet')}</p></div><span id="lab-save-state" class="save-state">Saved to your account</span></div>${r.mode==='peer'&&!r.evaluator_id?`<div class="panel"><h2>Share this pairing code with your evaluator</h2><p>Your peer signs in to their own account and chooses “Join as a peer evaluator” in Lab Practice. Only the paired evaluator can mark this peer checklist.</p><label for="lab-pairing-code">Pairing code</label><input id="lab-pairing-code" readonly value="${r.id}"><div class="actions"><button class="btn secondary" id="lab-copy">Copy code</button><button class="btn" id="lab-pair-refresh">Check peer connection</button></div><p class="small">Share the code only with your chosen classmate.</p></div>`:''}<details class="panel"><summary>Practice instructions and checklist sources</summary><ul>${r.checklist.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul><p><strong>Sources:</strong> ${r.checklist.sources.map(esc).join('; ')}</p><p>“CF” marks an action split from a source row marked [CF]. These flags identify review priorities. Only your instructor determines an official critical fail or competency result.</p></details><div class="panel lab-timer-panel"><div><strong id="lab-clock" aria-label="Elapsed practice time">${labTime(labSeconds())}</strong><p id="lab-time-note" class="small">Target 15:00 · ${labSeconds()>900?'Target exceeded. Continue safely and review timing.':'The timer does not stop the checklist.'}</p></div><div class="actions">${editable?'<button class="btn secondary" id="lab-timer-toggle">'+(labStartedAt===null?'Start / resume timer':'Pause timer')+'</button><button class="btn secondary" id="lab-save">Save progress</button>':''}<button class="btn secondary" data-action="print">Print</button></div></div>${r.status==='finished'?labReport(r):`<p class="small" id="lab-counts">${summary.completed.length} completed · ${summary.na.length} not applicable · ${summary.missed.length} unmarked / missed</p><nav class="stepper" aria-label="Assessment sections">${r.checklist.sections.map((sec,i)=>`<button data-lab-section="${i}" class="${i===labSection?'current':''}" ${i===labSection?'aria-current="step"':''}>${i+1}. ${esc(sec.title)}</button>`).join('')}</nav><div class="panel"><h2>${labSection+1}. ${esc(s.title)}</h2><p class="small">Tick an action only when observed. Leave missed actions unticked. For conditional actions, use Not applicable only when the condition is absent.</p>${s.actions.map((a,i)=>`<div class="lab-action ${a.cf?'lab-cf':''}"><label class="lab-check"><input type="checkbox" data-lab-action="${a.id}" ${r.results[a.id]==='done'?'checked':''} ${editable?'':'disabled'}><span><span class="small">${i+1}.</span> ${esc(a.text)} ${a.cf?'<span class="badge warning">CF</span>':''}</span></label>${a.conditional?`<label class="lab-na"><input type="checkbox" data-lab-na="${a.id}" ${r.results[a.id]==='na'?'checked':''} ${editable?'':'disabled'}> Not applicable</label>`:''}<details class="lab-source"><summary>Source criterion</summary><p class="small">${esc(a.sourceRow)}${a.cf?' · Original row marked [CF]':''}</p><p class="small">${esc(a.sourceText)}</p></details></div>`).join('')}<div class="field"><label for="lab-section-notes">Section feedback and reasons for Not applicable</label><textarea id="lab-section-notes" ${editable?'':'readonly'}>${esc(r.notes[s.id]||'')}</textarea></div><div class="actions">${labSection>0?'<button class="btn secondary" id="lab-previous">Previous section</button>':''}${labSection<r.checklist.sections.length-1?'<button class="btn" id="lab-next">Next section</button>':''}</div></div><div class="panel"><h2>Finish and review</h2><p>Finishing marks every remaining unticked applicable action as missed. The review separates CF-marked steps from other missed steps.</p>${editable?'<button class="btn" id="lab-finish">Finish practice and review missed steps</button>':'<p class="small">This view is read-only. '+(r.mode==='peer'?'Your paired peer evaluator completes this record.':'Only the learner can complete self-practice.')+'</p>'}<p id="lab-finish-error" role="alert"></p></div>`}`);document.getElementById('lab-back').onclick=async e=>{e.preventDefault();labPause();clearTimeout(labSaveTimer);if(!await labSave())return;labRun=null;labPractice()};document.getElementById('lab-copy')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(r.id);toast('Pairing code copied.')}catch{document.getElementById('lab-pairing-code').select();toast('Select and copy the pairing code.')}});document.getElementById('lab-pair-refresh')?.addEventListener('click',()=>labOpen(r.id));document.querySelectorAll('[data-lab-section]').forEach(b=>b.onclick=()=>{labSection=+b.dataset.labSection;labDrawRun();focusMain()});document.querySelectorAll('[data-lab-action]').forEach(b=>b.onchange=()=>{r.results[b.dataset.labAction]=b.checked?'done':'';labQueueSave();labUpdateCounts();const na=document.querySelector(`[data-lab-na="${b.dataset.labAction}"]`);if(na)na.checked=false});document.querySelectorAll('[data-lab-na]').forEach(b=>b.onchange=()=>{r.results[b.dataset.labNa]=b.checked?'na':'';document.querySelector(`[data-lab-action="${b.dataset.labNa}"]`).checked=false;labQueueSave();labUpdateCounts()});document.getElementById('lab-section-notes')?.addEventListener('input',e=>{r.notes[s.id]=e.target.value;labQueueSave()});document.getElementById('lab-previous')?.addEventListener('click',()=>{labSection--;labDrawRun();focusMain()});document.getElementById('lab-next')?.addEventListener('click',()=>{labSection++;labDrawRun();focusMain()});document.getElementById('lab-save')?.addEventListener('click',labSave);document.getElementById('lab-timer-toggle')?.addEventListener('click',()=>{if(labStartedAt===null){labStartedAt=Date.now();labTimer=setInterval(labUpdateClock,1000)}else{labPause();labQueueSave()}labDrawRun()});document.getElementById('lab-finish')?.addEventListener('click',labFinish);if(r.status==='finished'){document.getElementById('lab-download')?.addEventListener('click',()=>download('head-to-toe-practice-'+r.id+'.json',JSON.stringify(r,null,2),'application/json'));document.getElementById('lab-repeat')?.addEventListener('click',()=>{labRun=null;return labCreate(r.skill_id,r.mode)})}labUpdateClock()}
function labUpdateCounts(){const el=document.getElementById('lab-counts');if(el&&labRun){const s=labSummary(labRun);el.textContent=`${s.completed.length} completed · ${s.na.length} not applicable · ${s.missed.length} unmarked / missed`}}
function labUpdateClock(){if(!labRun)return;const el=document.getElementById('lab-clock'),note=document.getElementById('lab-time-note');if(el)el.textContent=labTime(labSeconds());if(note)note.textContent=labSeconds()>900?'Target 15:00 exceeded. Continue safely and review timing.':'Target 15:00 · The timer does not stop the checklist.'}
async function labFinish(){if(labFinishPending||!labRun||!labCanEdit(labRun))return;const r=labRun;const needsNotes=r.checklist.sections.filter(s=>s.actions.some(a=>r.results[a.id]==='na')&&!String(r.notes[s.id]||'').trim());const el=document.getElementById('lab-finish-error');if(needsNotes.length){el.textContent='Explain Not applicable choices in the notes for: '+needsNotes.map(s=>s.title).join('; ');return}if(labSeconds()===0){el.textContent='Start the timer before completing a timed practice run.';return}labFinishPending=true;labPause();clearTimeout(labSaveTimer);try{if(!await labSave())throw Error('Progress was not saved. Try saving again before finishing.');const results={...r.results};labActions(r).forEach(a=>{if(results[a.id]!=='done'&&!(a.conditional&&results[a.id]==='na'))results[a.id]='missed'});const rows=await api('lab_practice_sessions?id=eq.'+r.id,{method:'PATCH',body:{results,notes:r.notes,elapsed_seconds:r.elapsed_seconds,status:'finished',finished_at:new Date().toISOString()},prefer:'return=representation'});if(!rows?.length)throw Error('Could not finish this practice record. Refresh and try again.');labRun=rows[0];labDrawRun();focusMain()}catch(e){el.textContent=e.message;toast(e.message)}finally{labFinishPending=false}}
function labReport(r){const s=labSummary(r),noncf=s.missed.filter(a=>!a.cf);return `<div class="panel"><p class="eyebrow">Practice review</p><h2>${s.cf.length?'CF-marked actions need review':'No missed CF-marked actions recorded'}</h2><div class="stats"><div class="stat"><span>Completed actions</span><strong>${s.completed.length}</strong></div><div class="stat"><span>Missed actions</span><strong>${s.missed.length}</strong></div><div class="stat"><span>Missed CF-marked actions</span><strong>${s.cf.length}</strong></div></div><p>${s.completed.length} completed + ${s.missed.length} missed + ${s.na.length} not applicable = ${s.total} checklist actions.</p><p>Recorded time: <strong>${labTime(r.elapsed_seconds)}</strong> · Target: 15:00 · ${r.elapsed_seconds<=900?'Within the practice time target':'Beyond the practice time target'}.</p><div class="notice">Practice feedback only. A checked box does not establish competent technique. CF flags come from the supplied rubric rows; your instructor decides the official assessment outcome.</div><h3>Missed CF-marked steps (${s.cf.length})</h3>${labReportActions(s.cf)}<h3>Other missed steps (${noncf.length})</h3>${labReportActions(noncf)}<details><summary>Completed steps (${s.completed.length})</summary>${labReportActions(s.completed)}</details><details><summary>Not applicable steps (${s.na.length})</summary>${labReportActions(s.na)}</details><h3>Section feedback</h3>${r.checklist.sections.filter(sec=>r.notes[sec.id]).map(sec=>`<h4>${esc(sec.title)}</h4><p class="review-text">${esc(r.notes[sec.id])}</p>`).join('')||'<p>No notes recorded.</p>'}<p class="small">Checklist version ${esc(r.skill_version)} · Finished ${esc(new Date(r.finished_at).toLocaleString())}</p><div class="actions"><button class="btn secondary" id="lab-download">Download practice record</button>${r.learner_id===session.user.id?'<button class="btn" id="lab-repeat">Start another practice run</button>':''}</div></div>`}
function labReportActions(actions){return actions.length?`<ul>${actions.map(a=>`<li>${esc(a.text)} <small>(${esc(a.sourceRow)})</small></li>`).join('')}</ul>`:'<p>None recorded.</p>'}

boot();
